const idRecord = $node["Busca Gravação"].json.id;

// Determinar resultado baseado no tipo de análise
let statusFinal, isCaixaPostal, analiseCompleta;

if (tipoAnalise === 'caixa_postal') {
  // Análise simples de caixa postal
  const resultadoIA = analiseIA.output || analiseIA.message?.content?.toLowerCase() || '';
  isCaixaPostal = resultadoIA.includes('true');
  statusFinal = isCaixaPostal ? 'caixa' : 'atendida';
} else {
  // Análise completa com prompt personalizado
  analiseCompleta = analiseIA.output || analiseIA.message?.content || '';

  // Extrair classificação da análise completa
  const analiseTexto = analiseCompleta.toLowerCase();

  // Determinar status baseado no conteúdo da análise
  if (analiseTexto.includes('caixa postal')) {
    statusFinal = 'caixa';
    isCaixaPostal = true;
  } else if (analiseTexto.includes('não atendida') || analiseTexto.includes('nao atendida')) {
    statusFinal = 'nao_atend';
    isCaixaPostal = false;
  } else if (analiseTexto.includes('atendida')) {
    statusFinal = 'atendida';
    isCaixaPostal = false;
  } else if (analiseTexto.includes('desconhecida')) {
    statusFinal = 'desconhecida';
    isCaixaPostal = false;
  } else {
    // Se não conseguir determinar, assume atendida
    statusFinal = 'atendida';
    isCaixaPostal = false;
  }
}

