 /**
  * Formata duração em segundos para string legível (ex: "2min 30s")
  */
 function formatarDuracao(segundos) {
   const seg = parseInt(segundos) || 0;
   if (seg === 0) return "0s";

   const horas = Math.floor(seg / 3600);
   const minutos = Math.floor((seg % 3600) / 60);
   const segundosRestantes = seg % 60;

   let resultado = [];
   if (horas > 0) resultado.push(`${horas}h`);
   if (minutos > 0) resultado.push(`${minutos}min`);
   if (segundosRestantes > 0 || resultado.length === 0) resultado.push(`${segundosRestantes}s`);

   return resultado.join(' ');
 }

