function detectarRepeticao(text) {
  const palavras = text.toLowerCase().replace(/[.,!?;:'"()\-\*\[\]#]/g, '').split(/\s+/).filter(p => p.length > 0);
  const total = palavras.length;

  if (total < 20) return false;

  const freq = {};
  for (const p of palavras) {
    freq[p] = (freq[p] || 0) + 1;
  }
  for (const [palavra, count] of Object.entries(freq)) {
    if (count / total > 0.5) return true;
  }

  let consecutivo = 1;
  for (let i = 1; i < palavras.length; i++) {
    if (palavras[i] === palavras[i - 1]) {
      consecutivo++;
      if (consecutivo >= 10) return true;
    } else {
      consecutivo = 1;
    }
  }

  for (let n = 2; n <= 5; n++) {
    if (total < n * 10) continue;
    for (let offset = 0; offset < n; offset++) {
      const ngramCount = {};
      let totalNgrams = 0;
      for (let i = offset; i <= total - n; i += n) {
        const ngram = palavras.slice(i, i + n).join(' ');
        ngramCount[ngram] = (ngramCount[ngram] || 0) + 1;
        totalNgrams++;
      }
      for (const count of Object.values(ngramCount)) {
        if (totalNgrams >= 10 && count / totalNgrams > 0.7) return true;
      }
    }
  }

  for (let n = 1; n <= 4; n++) {
    const windowSize = Math.min(100, total);
    for (let start = 0; start <= total - windowSize; start += Math.floor(windowSize / 2)) {
      const janela = palavras.slice(start, start + windowSize);
      const ngramCount = {};
      const totalNgrams = janela.length - n + 1;
      for (let i = 0; i <= janela.length - n; i++) {
        const ngram = janela.slice(i, i + n).join(' ');
        ngramCount[ngram] = (ngramCount[ngram] || 0) + 1;
      }
      for (const count of Object.values(ngramCount)) {
        if (totalNgrams >= 20 && count / totalNgrams > 0.6) return true;
      }
    }
  }

  return false;
}

