/**
 * =================================
 * NÓ: Preparar Dados Redis - CONCORRÊNCIA MULTI-TOKEN
 * =================================
 * MOTIVO: Adicionar token_hash à chave Redis para permitir
 *         múltiplas execuções simultâneas do mesmo cliente
 *         quando possui tokens CRM diferentes
 * ENTRADA: $json (payload do "Verificar Envio CRM", com integracaoCRM embutido)
 * SAÍDA: { queue_key, clients_key, id_cliente, payload }
 * LÓGICA:
 *   1. Extrair CRM e id_cliente diretamente de $json
 *   2. Extrair token do CRM e gerar hash DJB2
 *   3. Montar chave Redis com 4 partes: queue:{CRM}:{id}:{hash}
 * WORKFLOW: PROCESSADOR-IA-GRAVACOES-V3
 * AUTOR: Claude + iFix
 * DATA: 2026-02-11
 * =================================
 */

// ===== FUNÇÃO HASH DE TOKEN (DJB2) =====
// Gera hash determinístico de 8 caracteres hex
// Mesma entrada SEMPRE produz mesma saída
function hashToken(token) {
  if (!token || typeof token !== 'string') return 'default';
  let hash = 5381;
  for (let i = 0; i < token.length; i++) {
    hash = ((hash << 5) + hash) + token.charCodeAt(i);
    hash = hash & hash;
  }
  return (Math.abs(hash) >>> 0).toString(16).padStart(8, '0');
}

// ===== CAPTURAR DADOS =====
// DIFERENÇA DO HIBRIDO: aqui é $json direto, NÃO $json.dados
const dados = $json;

// ===== NORMALIZAR CRM =====
// DIFERENÇA DO HIBRIDO: aqui é dados.crm, NÃO dados.integracaoCRM.crm
const crmKey = String(dados.crm || '').replace(/ /g, '_');
const idCliente = String(dados.id_cliente || '');

// ===== VALIDAÇÃO OBRIGATÓRIA =====
if (!crmKey || !idCliente) {
  console.error('❌ Campos obrigatórios faltando:', { crm: crmKey, id_cliente: idCliente });
  throw new Error('crm e id_cliente são obrigatórios para Fair Queue');
}

// ===== GERAR HASH DO TOKEN =====
// O token vem dentro de integracaoCRM (montado pelo nó "Verificar Envio CRM")
const tokenCRM = dados.integracaoCRM?.token_usuario_administrador_crm || null;
const tokenHash = hashToken(tokenCRM);

// ===== CHAVES REDIS (formato 4 partes) =====
const queueKey = `queue:${crmKey}:${idCliente}:${tokenHash}`;
const clientsKey = `clients:${crmKey}:active`;

// ===== PAYLOAD COMPLETO PARA A FILA =====
const payload = JSON.stringify(dados);

console.log('📤 [IA] Preparando Fair Queue:', {
  queue_key: queueKey,
  clients_key: clientsKey,
  crm: crmKey,
  id_cliente: idCliente,
  token_hash: tokenHash,
  token_presente: !!tokenCRM,
  tem_transcricao: dados.tem_transcricao
});

return {
  json: {
    // Chaves Redis
    queue_key: queueKey,
    clients_key: clientsKey,
    id_cliente: idCliente,

    // Payload serializado
    payload: payload,

    // Dados originais (para debug)
    _original: dados
  }
};

